<script>
  import QRCode from "../QRJS.svelte";
  import { pollForNewPayment } from "../../shared/utils/Polling.svelte";
  import BrandIcon from "../icons/BrandIcon.svelte";
  import BrandIconDark from "../icons/BrandIconDark.svelte";
  import ErrorIcon from "../icons/ErrorIcon.svelte";
  import SuccessIcon from "../icons/SuccessIcon.svelte";
  import { TENANT } from "../../tenant.js";

  export let isPwtModalVisible;
  export let paymentShortReference;
  export let loadDataError;
  export let paymentData;
  export let sessionId;
  export let qrCodeValue;
  export let onCloseModal;
  export let successUrl;
  export let errorUrl;

  // Detect if the user is from mobile phone by checking if the screen is touchable
  function isTouchDevice() {
    return "ontouchstart" in window || navigator.maxTouchPoints > 0;
  }

  function openToonieApp() {
    const appPaymentUrl = `${TENANT.deepLinkProtocol}:money-payment-session/${paymentData.offersSessionId}/pay?otp-token=${paymentData.otp}`;

    // Start the timeout for fallback action in case the app is not installed
    const timeout = setTimeout(() => {
      alert(TENANT.deepLinkErrorMessage);
    }, 1500);

    window.location.href = appPaymentUrl;

    // Clear the timeout if the user opens the app
    window.addEventListener("blur", () => clearTimeout(timeout));
  }
</script>

<div>
  <div class="pwt-modal {isPwtModalVisible ? 'pwt-modal--visible' : ''}">
    <div class="pwt-modal__content">
      <button on:click={onCloseModal} class="pwt-modal__close-icon">X</button>
      {#if isPwtModalVisible}
        {#if loadDataError}
          <div class="pwt-modal__body">
            <div class="pwt-modal__title pwt-modal__title--error">Error</div>
            <div class="pwt-modal__icon">
              <ErrorIcon />
            </div>
            <div class="pwt-modal__message">
              There was an issue with loading data for this payment
            </div>
            <button on:click={onCloseModal} class="pwt-modal__btn">Close</button
            >
          </div>
        {/if}
        {#if !loadDataError && !qrCodeValue}
          <p>Loading...</p>
        {/if}
        {#if qrCodeValue && paymentData && !loadDataError}
          {#await pollForNewPayment(paymentData, "PWT", successUrl, errorUrl, sessionId)}
            <div class="pwt-modal__body">
              <div class="pwt-modal__payment-data">
                <div class="pwt-modal__subtitle">Amount</div>
                {paymentData.amount}
                {paymentData.currency}
                <div class="pwt-modal__subtitle">Reason</div>
                {paymentData.reason}
              </div>
              <QRCode codeValue={qrCodeValue} />
              <div class="pwt-modal__message">
                Scan QR-code with your app or type letter-code
              </div>
              <div class="pwt-modal__letter-code">{paymentShortReference}</div>
              {#if isTouchDevice()}
                <button
                  on:click={openToonieApp}
                  class="pwt-modal__btn"
                  style="text-decoration: none"
                >
                  {TENANT.payButtonLabel}
                </button>
              {/if}
            </div>
          {:then}
            <div class="pwt-modal__body">
              <div class="pwt-modal__title">Done!</div>
              <div class="pwt-modal__icon">
                <SuccessIcon />
              </div>
              <div class="pwt-modal__message">
                Payment was successful! Redirecting...
              </div>
              <button on:click={onCloseModal} class="pwt-modal__btn"
                >Close</button
              >
            </div>
          {:catch error}
            <div class="pwt-modal__body">
              <div class="pwt-modal__title pwt-modal__title--error">Error</div>
              <div class="pwt-modal__icon">
                <ErrorIcon />
              </div>
              <div class="pwt-modal__message">{error.message}</div>
              <button on:click={onCloseModal} class="pwt-modal__btn">
                Close
              </button>
            </div>
          {/await}
        {/if}
      {/if}
      <div class="pwt-modal__footer">
        <span>Powered by</span>
        <div class="footer-svg">
          <BrandIconDark width={TENANT.logoSmallWidth} height={TENANT.logoSmallHeight} viewBox={TENANT.logoSmallViewBox} />
        </div>
      </div>
    </div>
  </div>
</div>

<style lang="scss">
  @import "../../styles/modal.styles.scss";
</style>
